import base64, json

def encode_cursor(offset: int, ts: int) -> str:
    raw = json.dumps({"o": offset, "t": ts}, separators=(",", ":")).encode()
    return base64.urlsafe_b64encode(raw).decode().rstrip("=")

def decode_cursor(c: str) -> dict:
    pad = "=" * (-len(c) % 4)
    return json.loads(base64.urlsafe_b64decode(c + pad))
